      inkCorrectLabel: '正确',
      inkFastest: '最快',
      inkTapReplay: '点击重新开始',
      inkSpaceReplay: '点击或按空格重新开始',

      // Lumina — Canvas UI
      lumAchFirstDive: '首次潜入',
      lumAchFirstDiveDesc: '到达深度1',
      lumAchDeepDiver: '深海潜水员',
      lumAchDeepDiverDesc: '到达深度10',
